UPDATE material_translations SET body='{"captions":["Zonele de vegetație ale Terrei – harta de ansamblu","Pădurile umede (ecuatoriale și musonice) – răspândirea pe glob","Pădurea ecuatorială – aspect general și etajarea vegetației pe verticală (4–6 straturi)","Vegetația pădurii ecuatoriale: arborele de cacao, palmierul de cocos, cafeaua, arborele de cauciuc, bananierul","Arbori prețioși ai pădurii ecuatoriale: mahon (acaju) și palisandru","Fauna pădurii ecuatoriale: tarantula, anaconda, pasărea colibri, broasca de copac, harpia, papagalul, fluturele albastru","Fauna pădurii ecuatoriale: urangutanul, jaguarul, okapi, gorila, capucinul, capibara, leneșul","Savana – răspândirea pe glob","Peisaj de savană – ierburi înalte cu arbori izolați (acacia)","Vegetația savanei: baobabul, acacia, eucaliptul","Fauna savanei: rinocerul, hipopotamul, bivolul, struțul, gazela","Fauna savanei: leul, leopardul, crocodilul, cangurul, ornitorincul","Pădurea musonică – arbori de esență tare: teckul și abanosul","Deșerturile și semideșerturile tropicale – răspândirea pe glob","Vegetația deșertului tropical: curmalul și cactușii","Fauna deșertului tropical: vipera, scorpionul, vulpea de deșert, dromaderul, șopârla","Zona mediteraneană (subtropicală) – răspândirea pe glob","Vegetația mediteraneană – tufișuri de maquis","Plante mediteraneene: bambusul, măslinul, stejarul de plută","Fauna mediteraneană: broasca țestoasă de uscat, vipera cu corn, scorpionul","Pădurea de foioase (mediul temperat-oceanic) – răspândirea pe glob","Pădure de foioase – aspect de toamnă","Plante ale pădurii de foioase: chiparosul și magnolia","Fauna pădurii de foioase: lupul, castorul, ratonul, vulpea, mistrețul, căprioara","Pădurea de conifere – taigaua (mediul temperat-rece) – răspândirea pe glob","Taigaua – pădure de conifere; arborele-gigant sequoia gigantea","Fauna taigalei: râsul, hermelina, cerbul, ursul brun","Stepa (mediul temperat-continental) – răspândirea pe glob","Peisaj de ierburi: stepa (Europa și Asia), preria (America de Nord), pampasul (America de Sud)","Fauna stepei: iepurele, hârciogul, popândăul, dropia, prepelița, potârnichea","Bizonul – animalul caracteristic preriei nord-americane","Deșerturile temperate – răspândirea pe glob (Gobi, Karakum)","Vegetația deșerturilor temperate: pelinul, saxaulul, agava, cactușii","Fauna deșerturilor temperate: coiotul și cămila bactriană (cu două cocoașe)","Tundra (mediul subpolar) – răspândirea pe glob","Tundra – peisaj cu plante mărunte, lipite de pământ","Vegetația tundrei: mușchi și licheni, afinul, merișorul","Fauna tundrei: renul (caribu), vulpea polară, iepurele arctic","Deșerturile reci – arctic și antarctic (mediul polar) – răspândirea pe glob","Fauna zonelor polare: ursul polar în Arctica; pinguinii în Antarctica"]}' WHERE material_id='07c35944-e7cd-457d-a1cb-6c65528b7dbf' AND locale='ro';
